const char* ROOT_CA = "-----BEGIN CERTIFICATE-----\n<PLACEHOLDER_ROOT_CA>\n-----END CERTIFICATE-----\n";


void reconnect() {
  while (!mqtt.connected()) {
    if (!mqtt.connect("esp32-node-31", MQTT_USER, MQTT_PASS)) delay(2000);
  }
}

